    /// Allow application to confirm indication. This command has to be sent when the application
    /// receives the [GATT Indication](crate::vendor::event::VendorEvent::GattIndication) event.
    ///
    /// # Errors
    ///
    /// Only underlying communication errors are reported.
    ///
    /// # Generated events
    ///
    /// A [command complete](crate::event::command::CommandComplete) event
    /// is generated when this command is processed.
    async fn confirm_indication(&self, conn_handle: crate::ConnectionHandle) -> Result<(), Error>;

    /// Allows or rejects a write request from a client.
    ///
    /// This command has to be sent by the application when it receives the
    /// [GATT Write Permit Request](crate::vendor::event::VendorEvent::AttWritePermitRequest) event.
    ///
    /// # Errors
    ///
    /// - [ValueBufferTooLong](Error::ValueBufferTooLong) if the
    ///   [attribute value](WriteResponseParameters::value) is so long that the serialized command cannot fit
    ///   in one packet. The maximum length is 250 bytes.
